<!doctype html><html lang="fr"><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:7px}h1{font-size:19px}</style><body><h1>Inscriptions baptême et première communion</h1><p>{{ $liste->campagne->titre }} — Classe {{ $liste->classe->nom }} — Version {{ $liste->version }}</p><p>État : {{ $liste->statut }}. Liste figée à la transmission.</p><table><thead><tr><th>Référence</th><th>Candidat</th><th>Sacrement</th><th>Contrôle effectué le</th><th>Décision individuelle</th></tr></thead><tbody>@foreach($liste->candidats as $c)<tr><td>{{ $c['reference'] }}</td><td>{{ $c['nom'] }}</td><td>{{ str_replace('_', ' ', $c['type']) }}</td><td>{{ \Carbon\Carbon::parse($c['controle']['observe_le'])->format('d/m/Y') }}</td><td>{{ collect($liste->journal)->contains(fn ($e) => ($e['action'] ?? '') === 'refus_candidat' && (int) ($e['candidat_id'] ?? 0) === (int) $c['id']) ? 'Refusé par le bureau' : (collect($liste->journal)->last(fn ($e) => ($e['action'] ?? '') === 'decision_candidat_pasteur' && (int) ($e['candidat_id'] ?? 0) === (int) $c['id'])['decision'] ?? 'Suit la décision de la liste') }}</td></tr>@endforeach</tbody></table><h2>Décisions</h2>@foreach($liste->journal as $e)<p>{{ $e['date'] }} — {{ $e['acteur'] }} : {{ $e['action'] }}. {{ $e['commentaire'] }}</p>@endforeach</body></html>
